const ls=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}},sv=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
const host=u=>{try{return new URL(u).hostname.replace(/^www\./,'')}catch(e){return u}};
const ENG={ddg:['DuckDuckGo','https://lite.duckduckgo.com/lite/?q=%s'],google:['Google','https://www.google.com/search?q=%s'],bing:['Bing','https://www.bing.com/search?q=%s'],brave:['Brave','https://search.brave.com/search?q=%s'],wiki:['Wikipedia','https://en.wikipedia.org/w/index.php?search=%s'],custom:['Custom','']};
const D={mode:'system',accent:'#1a73e8',tint:true,tabs:'classic',dens:'normal',ui:100,round:20,bmBar:true,homeBtn:true,homeUrl:'supreme://newtab',engine:'ddg',custom:'',proxy:'',ntpBg:''};
const S=Object.assign({},D,ls('so-s',{}));
const save=()=>sv('so-s',S);
let B=ls('so-b',[{u:'https://en.wikipedia.org/wiki/Main_Page',t:'wikipedia.org'},{u:'https://www.openstreetmap.org/export/embed.html',t:'openstreetmap.org'}]);
let H=ls('so-h',[]),SC=ls('so-sc',[['Wikipedia','https://en.wikipedia.org/wiki/Main_Page'],['Commons','https://commons.wikimedia.org'],['Wikivoyage','https://en.wikivoyage.org'],['OpenStreetMap','https://www.openstreetmap.org/export/embed.html'],['Example','https://example.com']]);
const eng=()=>S.engine==='custom'?(S.custom||ENG.ddg[1]):ENG[S.engine][1];
const looks=q=>/^([a-z][a-z0-9+.-]*:\/\/|about:blank)/i.test(q)?q:(/^(localhost|[^\s\/]+\.[a-z]{2,})(:\d+)?([\/?#]\S*)?$/i.test(q)?'https://'+q:null);
const resolve=q=>{q=(q||'').trim();return q?(looks(q)||eng().replace('%s',encodeURIComponent(q))):'supreme://newtab'};
const web=u=>/^https?:/.test(u);
const prox=u=>S.proxy?(S.proxy.indexOf('%s')>-1?S.proxy.replace('%s',encodeURIComponent(u)):S.proxy+u):u;

/* theme */
function theme(){
  const dark=S.mode==='dark'||(S.mode==='system'&&matchMedia('(prefers-color-scheme:dark)').matches),a=S.accent,st=A.style;
  const mix=(b,p)=>S.tint?'color-mix(in srgb,'+a+' '+p+'%,'+b+')':b;
  A.dataset.t=dark?'dark':'light';A.dataset.ts=S.tabs;A.dataset.d=S.dens;A.classList.toggle('nobm',!S.bmBar);
  st.setProperty('--accent',a);st.setProperty('--r',S.round+'px');
  st.setProperty('--strip',mix(dark?'#202124':'#dee1e6',dark?24:20));
  st.setProperty('--tb',mix(dark?'#35363a':'#ffffff',dark?9:5));
  st.setProperty('--omni',mix(dark?'#202124':'#f1f3f4',dark?12:10));
  ['strip','toolbar','bm'].forEach(i=>{const e=$(i);if(e)e.style.zoom=S.ui/100});
  if(homeB)homeB.style.display=S.homeBtn?'':'none';
}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>theme());

/* menus & toast */
let menuEl=null;
const closeMenu=()=>{if(menuEl){menuEl.remove();menuEl=null}};
function menu(x,y,items){
  closeMenu();const m=h('div',{class:'menu'});m.style.zoom=S.ui/100;
  items.forEach(it=>{if(!it)return m.append(h('div',{class:'msep'}));if(it.el)return m.append(it.el);
    m.append(h('div',{class:'mi'+(it.dis?' dis':''),onclick:()=>{closeMenu();it.fn&&it.fn()}},h('span',{class:'ck'},it.on?ic('check',16):null),it.l,h('span',{class:'k'},it.k||'')))});
  A.append(m);menuEl=m;m.style.left=Math.max(4,Math.min(x,innerWidth-m.offsetWidth-6))+'px';m.style.top=Math.min(y,innerHeight-m.offsetHeight-6)+'px';
}
addEventListener('mousedown',e=>{if(menuEl&&!menuEl.contains(e.target))closeMenu()},true);
addEventListener('blur',closeMenu);
let tt;function toast(m){A.querySelectorAll('.toast').forEach(x=>x.remove());const t=h('div',{class:'toast'},m);$('content').append(t);clearTimeout(tt);tt=setTimeout(()=>t.remove(),3200)}

/* chrome skeleton */
const btn=(i,tip,fn)=>h('div',{class:'tbtn',title:tip,onclick:fn},ic(i));
const tabsEl=h('div',{id:'tabs'}),content=h('div',{id:'content'}),bm=h('div',{id:'bm'});
