A.append(h('div',{id:'strip'},tabsEl,h('div',{class:'tbtn nt',title:'New tab (Alt+T)',onclick:()=>newTab()},ic('add'))),
  h('div',{id:'toolbar'},bBack,bFwd,bRel,homeB,omniw,h('div',{class:'me',title:'Profile'},'S'),kebab),bm,content);

/* tabs */
let tabs=[],cur=null,nid=1,drag=null,closed=[];
function setFav(w,u){w.className='fav';w.replaceChildren();
  if(web(u)){const im=h('img',{src:'https://www.google.com/s2/favicons?sz=32&domain='+host(u)});im.onerror=()=>{im.remove();w.classList.remove('im');w.textContent=host(u)[0].toUpperCase()};w.classList.add('im');w.append(im)}else w.textContent='S'}
const tname=u=>u==='supreme://newtab'?'New tab':u==='supreme://settings'?'Settings':u==='supreme://history'?'History':web(u)?host(u):u;
function updTab(t){
  if(t.load){t.fav.className='fav sp';t.fav.replaceChildren()}else if(t.favU!==t.url||t.fav.className.indexOf('sp')>-1){setFav(t.fav,t.url);t.favU=t.url}
  t.tt.textContent=tname(t.url);t.el.title=tname(t.url);t.el.classList.toggle('pin',t.pin);
}
function newTab(u,bg){
  const t={hist:[],i:-1,url:'',z:1,load:false,pin:false};
  t.fav=h('span',{class:'fav'});t.tt=h('span',{class:'tt'});
  t.el=h('div',{class:'tab',draggable:'true',onclick:()=>sel(t),onauxclick:e=>{if(e.button===1)close(t)},oncontextmenu:e=>{e.preventDefault();tmenu(t,e)}},t.fav,t.tt,
    h('span',{class:'x',onclick:e=>{e.stopPropagation();close(t)}},ic('close',14)));
  t.el.ondragstart=()=>{drag=t};t.el.ondragover=e=>e.preventDefault();
  t.el.ondrop=()=>{if(drag&&drag!==t){tabs.splice(tabs.indexOf(drag),1);tabs.splice(tabs.indexOf(t),0,drag);tabs.forEach(x=>tabsEl.append(x.el))}};
  t.pane=h('div',{class:'pane'});content.append(t.pane);tabsEl.append(t.el);tabs.push(t);
  nav(t,u||'supreme://newtab');if(!bg)sel(t);return t}
function sel(t){cur=t;tabs.forEach(x=>{x.el.classList.toggle('active',x===t);x.pane.classList.toggle('on',x===t)});ui()}
function close(t){
  const i=tabs.indexOf(t);if(t.url!=='supreme://newtab')closed.push(t.url);
  tabs.splice(i,1);t.el.remove();t.pane.remove();
  if(!tabs.length)return newTab();
  if(cur===t)sel(tabs[Math.min(i,tabs.length-1)])}
function tmenu(t,e){menu(e.clientX,e.clientY,[{l:'New tab to the right',fn:()=>{const n=newTab();tabs.splice(tabs.indexOf(n),1);tabs.splice(tabs.indexOf(t)+1,0,n);tabs.forEach(x=>tabsEl.append(x.el))}},null,
