  {l:'Close',fn:()=>close(t)},{l:'Close other tabs',fn:()=>tabs.filter(x=>x!==t).forEach(close)},{l:'Close tabs to the right',fn:()=>tabs.slice(tabs.indexOf(t)+1).forEach(close)},
  {l:'Reopen closed tab',k:'Alt+Shift+T',dis:!closed.length,fn:()=>newTab(closed.pop())}])}

/* navigation */
function nav(t,input,push){
  const u=resolve(input);
  if(push!==false){t.hist=t.hist.slice(0,t.i+1);t.hist.push(u);t.i++}
  t.url=u;
  if(web(u)){if(!H.length||H[0].u!==u)H.unshift({u:u,t:Date.now()});H=H.slice(0,400);sv('so-h',H)}
  render(t);ui()}
function go(d){const t=cur,n=t.i+d;if(n<0||n>=t.hist.length)return;t.i=n;t.url=t.hist[n];render(t);ui()}
function reload(){render(cur,true);ui()}
function stop(){try{cur.pane.querySelector('iframe').contentWindow.stop()}catch(e){}cur.load=false;updTab(cur);ui()}
