function render(t){
  const u=t.url;t.load=false;let el;
  if(u==='supreme://newtab')el=ntp(t);else if(u==='supreme://settings')el=settings();else if(u==='supreme://history')el=history(t);
  else{el=h('iframe',{class:'fr',src:u==='about:blank'?u:prox(u),sandbox:'allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox allow-modals allow-downloads allow-presentation'});
    t.load=u!=='about:blank';const done=()=>{t.load=false;updTab(t);ui()};el.addEventListener('load',done);setTimeout(done,12000);
    if(!t.warned&&web(u)){t.warned=true;toast('Blank page? Some sites refuse to load inside frames. Use ⋮ › Open in real browser tab.')}}
  t.pane.replaceChildren(el);if(el.tagName==='IFRAME'&&t.z!==1){el.style.transform='scale('+t.z+')';el.style.width=100/t.z+'%';el.style.height=100/t.z+'%'}
  updTab(t)}

/* toolbar state */
let focused=false;
function ui(){
  const t=cur;if(!t)return;
  bBack.classList.toggle('off',t.i<=0);bFwd.classList.toggle('off',t.i>=t.hist.length-1);
  bRel.replaceChildren(ic(t.load?'close':'reload'));
  pi.replaceChildren(ic(t.url==='supreme://newtab'?'search':'tune',18));
  starB.replaceChildren(ic(B.some(b=>b.u===t.url)?'star1':'star0',18));starB.style.color=B.some(b=>b.u===t.url)?'var(--accent)':'';starB.style.display=web(t.url)?'':'none';
  tabs.forEach(updTab);
  if(!focused){addr.value=t.url==='supreme://newtab'?'':t.url;
    disp.replaceChildren();
    if(web(t.url)){let x;try{x=new URL(t.url)}catch(e){x=null}
      if(x){const rest=(x.pathname+x.search+x.hash).replace(/^\/$/,'');disp.append(h('span',{},x.hostname.replace(/^www\./,'')),h('span',{class:'m'},rest))}}
    else if(t.url!=='supreme://newtab')disp.append(t.url);
    addr.classList.toggle('h',t.url!=='supreme://newtab')}
  document.title=tname(t.url)+' - Supreme';
}
function star(){const t=cur;if(!web(t.url))return;const i=B.findIndex(b=>b.u===t.url);
  if(i>-1){B.splice(i,1);toast('Bookmark removed')}else{B.push({u:t.url,t:host(t.url)});toast('Bookmark added')}
  sv('so-b',B);bmr();ui()}
function bmr(){bm.replaceChildren(...B.map(b=>{const f=h('span',{class:'fav'});setFav(f,b.u);
  return h('div',{class:'bk',title:b.u,onclick:e=>e.ctrlKey?newTab(b.u,true):nav(cur,b.u),onauxclick:e=>{if(e.button===1)newTab(b.u,true)},
    oncontextmenu:e=>{e.preventDefault();menu(e.clientX,e.clientY,[{l:'Open in new tab',fn:()=>newTab(b.u)},{l:'Delete',fn:()=>{B=B.filter(x=>x!==b);sv('so-b',B);bmr();ui()}}])}},f,b.t)}))}

/* omnibox */
let items=[],si=-1;
function sugg(q){
  q=q.trim();const lq=q.toLowerCase();items=[];
  if(q){const u=looks(q);items.push(u?{i:'ext',t:q,m:'Open',u:q}:{i:'search',t:q,m:'Search '+(S.engine==='custom'?'':ENG[S.engine][0]),u:q})}
  B.forEach(b=>{if(!q||b.u.toLowerCase().indexOf(lq)>-1)items.push({i:'star1',t:b.u.replace(/^https?:\/\//,''),m:'Bookmark',u:b.u})});
  if(q)H.forEach(x=>{if(x.u.toLowerCase().indexOf(lq)>-1)items.push({i:'reload',t:x.u.replace(/^https?:\/\//,''),m:'History',u:x.u})});
  SC.forEach(s=>{if(!q||s[0].toLowerCase().indexOf(lq)>-1)items.push({i:'search',t:s[0],m:host(s[1]),u:s[1]})});
  items=items.filter((a,i,r)=>r.findIndex(b=>b.u===a.u)===i).slice(0,8);si=-1;drawSug();
}
function drawSug(){sug.replaceChildren(...items.map((it,i)=>{const d=h('div',{class:'si'+(i===si?' s':'')},ic(it.i,18),h('span',{class:'t'},it.t),h('span',{class:'sm'},it.m));
  d.addEventListener('mousedown',e=>{e.preventDefault();pick(it.u)});return d}));sug.classList.toggle('on',items.length>0&&focused)}
function pick(u){focused=false;sug.classList.remove('on');addr.blur();nav(cur,u)}
addr.addEventListener('focus',()=>{focused=true;pill.classList.add('f');addr.classList.remove('h');addr.value=cur.url==='supreme://newtab'?'':cur.url;disp.replaceChildren();setTimeout(()=>addr.select(),0);sugg('')});
addr.addEventListener('blur',()=>{focused=false;pill.classList.remove('f');sug.classList.remove('on');ui()});
addr.addEventListener('input',()=>sugg(addr.value));
addr.addEventListener('keydown',e=>{
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const n=items.length||1;si=(si+(e.key==='ArrowDown'?1:-1)+n)%n;drawSug();if(items[si])addr.value=items[si].u}
  else if(e.key==='Enter'){e.preventDefault();pick(si>=0&&items[si]?items[si].u:addr.value)}
  else if(e.key==='Escape')addr.blur()});

/* kebab menu */
function kmenu(x,y){
  const zb=(l,fn)=>h('div',{class:'zb',onclick:fn},l),zv=h('span',{style:'width:44px;text-align:center'},Math.round(cur.z*100)+'%');
  const zr=h('div',{class:'mi',style:'cursor:default'},h('span',{class:'ck'}),'Zoom',h('span',{class:'k',style:'display:flex;align-items:center;gap:4px'},zb('−',()=>{zoom(cur,-.1);zv.textContent=Math.round(cur.z*100)+'%'}),zv,zb('+',()=>{zoom(cur,.1);zv.textContent=Math.round(cur.z*100)+'%'})));
  menu(x,y,[{l:'New tab',k:'Alt+T',fn:()=>newTab()},{l:'New window',fn:()=>window.open(location.href,'_blank')},null,
    {l:'History',k:'Alt+H',fn:()=>newTab('supreme://history')},{l:'Show bookmarks bar',on:S.bmBar,k:'Ctrl+Shift+B',fn:()=>{S.bmBar=!S.bmBar;save();theme()}},null,{el:zr},
    {l:'Print…',fn:()=>window.print()},{l:'Full screen',k:'F11',fn:()=>{try{document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen()}catch(e){}}},null,
    {l:'Open in real browser tab',dis:!web(cur.url),fn:()=>window.open(cur.url,'_blank','noopener')},{l:'Settings & customize',fn:()=>newTab('supreme://settings')}])}

/* internal pages */
function ntp(t){
  const inp=h('input',{class:'ntpin',placeholder:'Search '+(S.engine==='custom'?'':ENG[S.engine][0]+' ')+'or type a URL',spellcheck:'false'});
  inp.onkeydown=e=>{if(e.key==='Enter'&&inp.value.trim())nav(t,inp.value)};
  const tiles=h('div',{class:'tiles'},SC.map((s,i)=>{const f=h('div',{class:'ci'});if(web(s[1])){const im=h('img',{src:'https://www.google.com/s2/favicons?sz=64&domain='+host(s[1])});im.onerror=()=>{im.remove();f.textContent=s[0][0]};f.append(im)}else f.textContent=s[0][0];
    return h('div',{class:'sc',onclick:()=>nav(t,s[1]),oncontextmenu:e=>{e.preventDefault();menu(e.clientX,e.clientY,[{l:'Remove shortcut',fn:()=>{SC.splice(i,1);sv('so-sc',SC);render(t)}}])}},f,s[0])}),
    h('div',{class:'sc',onclick:()=>{const n=prompt('Shortcut name');const u=n&&prompt('Shortcut URL');if(u){SC.push([n,resolve(u)]);sv('so-sc',SC);render(t)}}},h('div',{class:'ci'},ic('add')),'Add shortcut'));
  const el=h('div',{class:'ntp'},h('div',{class:'logo'},'Supreme'),inp,tiles,h('div',{class:'cust',onclick:()=>nav(t,'supreme://settings')},ic('tune',16),'Customize Supreme'));
  if(S.ntpBg)el.style.background=/^(https?:|data:)/.test(S.ntpBg)?'url("'+S.ntpBg+'") center/cover':S.ntpBg;
  setTimeout(()=>{if(t===cur)inp.focus()},50);return el}
function history(t){
  const q=h('input',{class:'ti',placeholder:'Search history',style:'width:100%'}),list=h('div',{});
  const draw=()=>{const f=q.value.toLowerCase();list.replaceChildren(...H.filter(x=>x.u.toLowerCase().indexOf(f)>-1).slice(0,150).map(x=>h('div',{class:'hi',onclick:()=>nav(t,x.u)},h('span',{class:'d'},new Date(x.t).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})),host(x.u),h('span',{class:'u'},x.u))))};
  q.oninput=draw;draw();
  return h('div',{class:'set'},h('h1',{},'History'),h('div',{class:'card'},h('div',{style:'padding:14px 20px;display:flex;gap:12px'},q,h('button',{class:'pb',style:'white-space:nowrap',onclick:()=>{H=[];sv('so-h',H);draw()}},'Clear all')),list))}
function settings(){
  const row=(l,c,s)=>h('div',{class:'row'},h('div',{},h('div',{class:'rl'},l),s?h('div',{class:'rs'},s):null),c);
  const seg=(k,o)=>{const w=h('div',{class:'seg'});o.forEach(p=>{const b=h('button',{class:S[k]===p[0]?'on':'',onclick:()=>{S[k]=p[0];save();theme();[...w.children].forEach(c=>c.classList.toggle('on',c===b))}},p[1]);w.append(b)});return w};
  const tog=k=>{const s=h('div',{class:'sw'+(S[k]?' on':''),onclick:()=>{S[k]=!S[k];save();theme();s.classList.toggle('on',S[k])}},h('i'));return s};
  const rng=(k,a,b)=>{const r=h('input',{type:'range',min:a,max:b,value:S[k]});r.oninput=()=>{S[k]=+r.value;save();theme()};return r};
  const txt=(k,ph)=>{const i=h('input',{class:'ti',placeholder:ph,value:S[k]});i.oninput=()=>{S[k]=i.value;save()};return i};
  const sws=h('div',{class:'sws'},['#1a73e8','#0b8043','#e8710a','#d93025','#9334e6','#d01884','#188038','#5f6368'].map(c=>{const d=h('div',{class:'swc',style:'background:'+c,onclick:()=>{S.accent=c;save();theme()}});return d}),
    (()=>{const i=h('input',{type:'color',value:S.accent,title:'Custom color'});i.oninput=()=>{S.accent=i.value;save();theme()};return i})());
  const sel=h('select',{class:'ti'},Object.keys(ENG).map(k=>h('option',{value:k},ENG[k][0])));sel.value=S.engine;sel.onchange=()=>{S.engine=sel.value;save()};
  return h('div',{class:'set'},h('h1',{},'Settings'),
    h('div',{class:'card'},h('h2',{},'Appearance'),
      row('Mode',seg('mode',[['light','Light'],['dark','Dark'],['system','Device']])),
      row('Theme color',sws),row('Tint browser with theme color',tog('tint')),
      row('Tab style',seg('tabs',[['classic','Classic'],['rounded','Rounded'],['square','Square']])),
      row('Toolbar density',seg('dens',[['compact','Compact'],['normal','Normal'],['roomy','Roomy']])),
      row('Address bar roundness',rng('round',2,20)),row('Interface size',rng('ui',85,130),'Scales tabs, toolbar and menus')),
    h('div',{class:'card'},h('h2',{},'Toolbar and startup'),
      row('Show bookmarks bar',tog('bmBar')),row('Show home button',tog('homeBtn')),
      row('Home page',txt('homeUrl','supreme://newtab'))),
    h('div',{class:'card'},h('h2',{},'Search and network'),
      row('Search engine',sel),row('Custom search URL',txt('custom','https://example.com/?q=%s'),'Used when the engine is set to Custom'),
      row('Proxy / URL prefix',txt('proxy','https://proxy.example/?url=%s'),'Optional. Use %s for the encoded page URL, or leave it out to prepend the prefix')),
    h('div',{class:'card'},h('h2',{},'New tab page'),
      row('Background',txt('ntpBg','Color, gradient or image URL'),'Example: #101820 or https://…/photo.jpg'),
      row('Shortcuts',h('button',{class:'pb',onclick:()=>{SC=JSON.parse(JSON.stringify(D&&[['Wikipedia','https://en.wikipedia.org/wiki/Main_Page'],['Commons','https://commons.wikimedia.org']]));sv('so-sc',SC);toast('Shortcuts reset')}},'Reset shortcuts'),'Right-click a shortcut to remove it')),
    h('div',{class:'card'},h('h2',{},'Privacy'),
      row('Browsing history',h('button',{class:'pb',onclick:()=>{H=[];sv('so-h',H);toast('History cleared')}},'Clear')),
      row('Reset all settings',h('button',{class:'pb',onclick:()=>{Object.assign(S,D);save();theme();render(cur)}},'Reset'))))}

/* shortcuts */
document.addEventListener('keydown',e=>{
  const k=e.key.toLowerCase(),c=e.ctrlKey||e.metaKey;
  if(e.altKey&&!c){
    if(k==='t'&&e.shiftKey){e.preventDefault();closed.length&&newTab(closed.pop())}
    else if(k==='t'){e.preventDefault();newTab()}else if(k==='w'){e.preventDefault();close(cur)}
    else if(k==='l'){e.preventDefault();addr.focus()}else if(k==='r'){e.preventDefault();reload()}
    else if(k==='h'){e.preventDefault();newTab('supreme://history')}else if(k==='home'){e.preventDefault();nav(cur,S.homeUrl)}
    else if(e.key==='ArrowLeft'){e.preventDefault();go(-1)}else if(e.key==='ArrowRight'){e.preventDefault();go(1)}
    else if(/^[1-9]$/.test(k)){e.preventDefault();sel(tabs[k==='9'?tabs.length-1:Math.min(+k-1,tabs.length-1)])}
    else if(k==='pagedown'||k==='pageup'){e.preventDefault();sel(tabs[(tabs.indexOf(cur)+(k==='pagedown'?1:-1)+tabs.length)%tabs.length])}
  }else if(c){
    if(k==='l'){e.preventDefault();addr.focus()}else if(k==='d'){e.preventDefault();star()}
    else if(k==='r'){e.preventDefault();reload()}else if(k==='b'&&e.shiftKey){e.preventDefault();S.bmBar=!S.bmBar;save();theme()}
    else if(k==='='||k==='+'){e.preventDefault();zoom(cur,.1)}else if(k==='-'){e.preventDefault();zoom(cur,-.1)}else if(k==='0'){e.preventDefault();zoom(cur,0)}
  }else if(e.key==='F5'){e.preventDefault();reload()}else if(e.key==='Escape'&&cur.load)stop();
});
theme();bmr();newTab();
})();
